    "id": "W3_Notebook_W6_Pregnancy_Parturition_Puerperium_39Q_29",
    "week": "W3",
    "lecture": "8.31 (Notebook)",
    "file": "Notebook_W6_Pregnancy_Parturition_Puerperium_39Q.md",
